class PublicOpportunityShiftEnrollmentRosterShareViewAPIView(generics.GenericAPIView):
    authentication_classes = ()
    permission_classes = [permissions.AllowAny]
    def get(self, request, *args, **kwargs):
        token = self.kwargs.get("token")
        rl = _rate_limit_or_none(request=request, scope="public_view", token=token, limit=120, window_seconds=60)
        if rl is not None: return rl
        share = OpportunityShiftEnrollmentRosterShareToken.get_by_token(token)
        if not share: return Response(status=404)
        if share.is_revoked: return Response(status=410)
        if share.is_expired: return Response(status=410)
